using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
namespace PowerShapeBridge {
 internal static class OwnedCurveScaleTests {
  static void Need(bool ok,string e){if(!ok)throw new InvalidOperationException(e);}
  static Dictionary<string,object> Clone(object x){return Program.Json.Deserialize<Dictionary<string,object>>(Program.Json.Serialize(x));}
  internal sealed class Context:OwnedSolidScale.IExecutionContext,OwnedTranslation.IContext,OwnedCurveTranslation.IContext,OwnedCurveScaleMeasurements.IPhaseGuard,NativeSelectionReading.IContext,OwnedSelection.IContext {
   internal Dictionary<string,object> Snapshot,Listing;internal string Fault;internal int FailPhase=-1,Calls;internal bool Selected,Applied;internal int RecoveryCalls;internal string RecoveryFault;
   OwnedCurveTranslationTests.Context Base(){return new OwnedCurveTranslationTests.Context{Snapshot=Snapshot,Listing=Listing};}
   public Dictionary<string,object> Observation(){var o=Clone(Snapshot);if(Selected){o["contextBefore"]=new[]{1,0};o["contextAfter"]=new[]{1,0};o["selectionBefore"]=new[]{new Dictionary<string,object>{{"type","Composite Curve"},{"name","Synthetic_59"}}};o["selectionAfter"]=o["selectionBefore"];}return o;}public Dictionary<string,object> Windows(){return Clone(Listing);}public void ConfirmDocument(){}public void Dispose(){}
   public int Composite(int t,int n){return Base().Composite(t,n);}public double[] Bounds(int n){return Base().Bounds(n);}public object ClosestSolidFace(int n,double[] p){return Base().ClosestSolidFace(n,p);}public object FaceNear(string n,double[] p){return Base().FaceNear(n,p);}public object FacePoint(string n,double t,double u,bool normal){var value=(double[])Base().FacePoint(n,t,u,normal);if(Applied&&Fault=="solid"&&!normal)value[0]+=0.001;return value;}
   public int SelectionCount(){return Selected?1:0;}
   public void ChangeSelection(OwnedSelectionProgram p){Need(p.Take()=="SELECT CLEARLIST","Recovery emitted another command");RecoveryCalls++;Selected=false;if(RecoveryFault=="throw")throw new IOException("Lost clear return");if(RecoveryFault=="drift")Applied=true;}
   public object ModelItems(){return EntitySets.Inventory(Snapshot).Select(e=>Composite((int)e["nativeTypeCode"],(int)e["nativeId"])).ToArray();}
   public object SelectedItems(){return Selected?new[]{Fault=="stop_other"?40:1180000010}:new int[0];}
   public object ItemData(object composites){var ids=((System.Collections.IEnumerable)composites).Cast<object>().Select(Convert.ToInt32).ToArray();var rows=ids.Select(id=>EntitySets.Inventory(Snapshot).Single(e=>Composite((int)e["nativeTypeCode"],(int)e["nativeId"])==id)).ToArray();return new object[]{rows.Select(e=>(int)e["nativeTypeCode"]).ToArray(),rows.Select(e=>(int)e["nativeId"]).ToArray(),rows.Select(e=>(string)e["name"]).ToArray(),rows.Select(e=>(int)e["levelNumber"]).ToArray()};}
   public int CurvePointCount(int n){return Base().CurvePointCount(n);}public int Translate(int n,double[] v){throw new InvalidOperationException("Scale called TranslateItem");}
   public object CurvePoints(string name,int start,int end){if(Selected)throw new InvalidOperationException("Autodesk GetCompCurvePointData denies nonempty selection");var value=(Array)Base().CurvePoints(name,start,end);if(!Applied){if(Selected&&Fault=="stop_point"){var a=(Array)value.GetValue(2);a.SetValue(999.0,1,1);}return value;}foreach(int field in new[]{0,1,2,5,6}){var a=(Array)value.GetValue(field+2);bool vector=a.Rank==2;for(int i=0;i<4;i++)for(int j=0;j<(vector?3:1);j++){double x=Convert.ToDouble(vector?a.GetValue(i+1,j+1):a.GetValue(i+1));double y=field==0?new[]{2.0,-3,4}[j]+1.25*(x-new[]{2.0,-3,4}[j]):field==2||field==6?x*1.25:x;if(i==0&&j==0&&(Fault=="point"&&field==0||Fault=="direction"&&field==1||Fault=="magnitude"&&field==2))y+=1;if(vector)a.SetValue(y,i+1,j+1);else a.SetValue(y,i+1);}}if(Fault=="flag")((Array)value.GetValue(5)).SetValue(true,1);return value;}
   public void ScalePhaseGuard(Dictionary<string,object> e,string name,int i,int windows){throw new InvalidOperationException("Curve called SOLID guard");}
   public void CurveScalePhaseGuard(Dictionary<string,object> e,string name,int i,int windows){if(Fault=="guard1"&&i==1)throw new InvalidOperationException("Selected descriptor rejected before phase1");Need(name=="Synthetic_59"&&Selected==(i>0)&&windows==1,"Curve phase target/count differs");}
   public void ScalePhase(SolidUniformScaleProgram p,int i){p.Take(i);Need(p.Commands[0]=="SELECT CLEARLIST ADD COMPCURVE 'Synthetic_59'"&&p.Commands[9]=="VALUE 1.25","Wrong typed curve command");Calls++;if(i==FailPhase)throw new IOException("Lost return at explicit phase");if(i==0)Selected=true;if(i==10){Applied=true;var g=(Dictionary<string,object>)EntitySets.Inventory(Snapshot).Single(e=>Equals(e["nativeTypeCode"],59))["geometry"];foreach(string k in new[]{"min_rangeRaw","max_rangeRaw"}){var v=((System.Collections.IEnumerable)g[k]).Cast<object>().Select(Convert.ToDouble).ToArray();for(int j=0;j<3;j++)v[j]=new[]{2.0,-3,4}[j]+1.25*(v[j]-new[]{2.0,-3,4}[j]);if(Fault=="range")v[0]+=1;g[k]=v;}g["lengthRaw"]=Fault=="length"?80:100;g["areaRaw"]=Fault=="area"?400:625;}if(i==12)Selected=false;}
  }
  internal static int Run(){Need(File.Exists(Path.Combine(Program.Root,".curve-scale-fixture")),"Explicit isolated fake curve-scale marker required; never CAD.");var rows=new List<object>();int checks=0;
   foreach(string fault in new[]{"control","point","direction","magnitude","flag","solid","range","length","area","phase0","phase10","phase12"}){
    var f=new OwnedOperationPlanTests.Fixture(true,true,false,true);var c=new Context{Snapshot=Clone(f.Snapshot),Listing=Clone(f.Listing),Fault=fault,FailPhase=fault.StartsWith("phase")?int.Parse(fault.Substring(5)):-1};var args=new Dictionary<string,object>{{"entitySetId",f.SetId},{"entitySetSha256",Program.Hash(Path.Combine(f.Root,"entitysets",f.SetId+".json"))},{"bindingId",f.BindingId},{"bindingSha256",f.Parameters["bindingSha256"]},{"parameters",new Dictionary<string,object>{{"factor",1.25},{"centre",new[]{2,-3,4}},{"coordinateFrame","world"},{"lengthUnits","document_raw"},{"mode","scale_in_place"}}},{"curveRange",new Dictionary<string,object>{{"startIndex",1},{"endIndex",4}}}};
    string preparedId=Guid.NewGuid().ToString("N");var p=OwnedSolidScale.Prepare(f.Root,preparedId,args,c,false,true);Need(Equals(p["state"],"owned_uniform_scale_prepared_observed")&&Equals(p["qualificationScope"],OwnedCurveScaleMeasurements.Scope),Program.Json.Serialize(p));string psha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",preparedId+".json"),p);var refs=new Dictionary<string,object>{{"ownedScaleId",preparedId},{"ownedScaleSha256",p["ownedScaleSha256"]},{"preparationReceiptSha256",psha},{"membershipBundleSha256",p["membershipBundleSha256"]}};
    string id=Guid.NewGuid().ToString("N");var e=OwnedSolidScale.Execute(f.Root,id,refs,c,false,true);bool partial=c.FailPhase>=0;Need(Equals(e["state"],partial?"owned_curve_scale_outcome_unknown":"owned_curve_scale_executed_unverified"),Program.Json.Serialize(e));Need(c.Calls==(partial?c.FailPhase+1:13),"Unexpected repeated/missing phase callback");checks++;
    string esha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",id+".json"),e);Need(Equals(OwnedSolidScale.Execute(f.Root,Guid.NewGuid().ToString("N"),refs,c,false,true)["state"],"owned_curve_scale_rejected_before_change"),"Scale replay reached callback");checks++;
    if(partial){rows.Add(new{fault,root=f.Root,executionId=id,calls=c.Calls});continue;}
    var j=NativeJournal.ForVerification(f.Root,id,(string)e["planSha256"]);var stamp=DateTime.UtcNow;if(stamp<=j.CommandReturnedUtc)stamp=j.CommandReturnedUtc.AddTicks(1);var o=c.Observation();o["timestampUtc"]=stamp.ToString("o");var w=c.Windows();w["state"]="documents_listed_verified";w["timestampUtc"]=stamp.AddTicks(1).ToString("o");string inspect=Guid.NewGuid().ToString("N"),listing=Guid.NewGuid().ToString("N"),vid=Guid.NewGuid().ToString("N");var proof=new Dictionary<string,object>{{"executionRequestId",id},{"executionReceiptSha256",esha},{"inspectionRequestId",inspect},{"inspectionSha256",NativeJournal.Freeze(Path.Combine(f.Root,"responses",inspect+".json"),o)},{"listingRequestId",listing},{"listingSha256",NativeJournal.Freeze(Path.Combine(f.Root,"responses",listing+".json"),w)},{"windowNumber",1},{"modelId",9},{"expiresUtc",DateTime.UtcNow.AddSeconds(150).ToString("o")}};
    var v=OwnedSolidScale.Verify(f.Root,vid,proof,c,false,false,true);Need(Equals(v["state"],fault=="control"?"owned_curve_scale_samples_match_unqualified":"owned_curve_scale_verification_rejected"),Program.Json.Serialize(v));Need(File.Exists(OwnedTranslation.FencePath(f.Root,(string)e["copyId"]))&&c.Calls==13,"Fake/failed surface verification released fence or replayed phase");string vsha=NativeJournal.Freeze(Path.Combine(f.Root,"responses",vid+".json"),v);checks++;rows.Add(new{fault,root=f.Root,preparationId=preparedId,preparationSha256=psha,references=refs,executionId=id,executionSha256=esha,verificationId=vid,verificationSha256=vsha,verificationArguments=proof,verificationResult=v});
   }
   bool typed=false;try{new SolidUniformScaleProgram("1",1.25,new[]{2.0,-3,4},58);}catch(ArgumentException){typed=true;}Need(typed,"Arbitrary scale command target accepted");checks++;
   Need(DocumentBindings.ComContext.ScaleSelectionMatches("COMPCURVE","2","Composite Curve","2"),"Actual PowerShape selection descriptor rejected");checks++;
   Need(!DocumentBindings.ComContext.ScaleSelectionMatches("COMPCURVE","2","Composite Curve","3")&&!DocumentBindings.ComContext.ScaleSelectionMatches("COMPCURVE","2","Curve","2"),"Wrong selected type/name accepted");checks++;
   Need(DocumentBindings.ComContext.ScaleSelectionMatches("SOLID","1","SOLID","1")&&DocumentBindings.ComContext.ScaleSelectionMatches("SURFACE","1","SURFACE","1")&&!DocumentBindings.ComContext.ScaleSelectionMatches("SOLID","1","Composite Curve","1"),"Existing typed guards weakened");checks++;
   Directory.CreateDirectory(Path.Combine(Program.Root,"reports"));NativeJournal.Freeze(Path.Combine(Program.Root,"reports","curve-scale-tests.json"),new{state="passed",checks,rows,cadConnectionAttempted=false});Console.WriteLine("PASS: "+checks+" curve scale phase-stop/replay/controls/directions/magnitudes/flags/SOLID controls; no CAD.");return checks;
  }
 }
